def add(doc,page,qtype,question,answer,explanation,options=None,context=None,rubric=None):
 d=docs[doc];n=sum(q['topic']==doc for q in qs)+1;fmt={'true_false':'boolean','short_answer':'rubric','scenario':'rubric' if rubric else 'single_choice'}.get(qtype,qtype)
 q={'id':f'{doc}-q{n:02}','revision':1,'author_id':'a1-question-engineer','phase':d['phase'],'track':d['track'],'day':doc,'topic':doc,'taxonomy_status':'verified','question_type':qtype,'answer_format':fmt,'difficulty':'medium','cognitive_level':'apply' if qtype=='scenario' else 'understand','question':question,'correct_answer':answer,'explanation':explanation,'source_reference':[{'document_id':doc,'sha256':d['sha256'],'pdf_page':page,'title':d['title'],'locator':f'Physical PDF page {page}; local extracted cache available by SHA256','verification':'needs_review'}],'status':'pending_review','review_notes':['Curricular mapping verified by root folder/filename policy; printed cover conflicts remain in catalog.','OCR en-US text used for authoring; independent reviewer must inspect rendered cited page.']}
